Definition init_statics1 (M : word -> option byte) : Prop :=
     (forall a : word, 0xecfc8 <= bv_unsigned a < 0xed378 -> M a = None)
  /\ (forall a : word, RVMLOCKC <= bv_unsigned a < RVMLOCKC + 4 -> M a = None)      (* [comment removed for export] *)
  /\ rw_cells rsegs M 0xece53 [C1 (Z_to_bv 8 0)]
  /\ rw_cells rsegs M 0xece80 [C8 (Z_to_bv 64 4096)]
  /\ rw_cells rsegs M 0xb9e20 [C8 (Z_to_bv 64 0xece30)]
  /\ (exists canary : Z, 0 <= canary < 2 ^ 64 /\ rw_cells rsegs M 0xece30 [C8 (Z_to_bv 64 canary)])
  /\ (exists (av x3 x4 x5 hw x6 x11 x12 x23 rnd secret : Z),
         rw_cells rsegs M 0xece58 [C8 (Z_to_bv 64 av)]
      /\ bytes_at rsegs M av (u64s (map (Z_to_bv 64) [3; x3; 4; x4; 5; x5; 16; hw; 6; x6; 11; x11; 12; x12; 23; x23; 25; rnd; 0; 0]))
      /\ bytes_at rsegs M (rnd + 8) (le8 (Z_to_bv 64 secret))
      /\ sptop <= av /\ av + 160 <= 2 ^ 64 /\ sptop <= rnd + 8 /\ rnd + 16 <= 2 ^ 64
      /\ 0 <= x3 < 2 ^ 64 /\ 0 <= x4 < 2 ^ 64 /\ 0 <= x5 < 2 ^ 64 /\ 0 <= hw < 2 ^ 64 /\ 0 <= x6 < 2 ^ 64
      /\ 0 <= x11 < 2 ^ 64 /\ 0 <= x12 < 2 ^ 64 /\ 0 <= x23 < 2 ^ 64 /\ 0 <= rnd < 2 ^ 64 /\ 0 <= secret < 2 ^ 64)
  /\ mem_inv rsegs M.

